let cleanupExplore=()=>{};
let cleanupEntrances=()=>{};
const C = window.BEARAI;
const esc = value => String(value ?? '').replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const routes = [['','Home'],['about','About'],['people','People'],['events','Events'],['resources','Resources'],['connections','Connections'],['recognition','Recognition'],['projects','Projects'],['community','Community'],['join','Join BearAI']];
const link = (path,label,cls='text-link') => `<a class="${cls}" href="#/${path}">${label}</a>`;
const badge = text => `<span class="badge">${text}</span>`;
const pending = text => `<button class="disabled" disabled>${text} · Coming soon</button>`;
const intro = (label,title,text) => `<div class="page-intro"><span class="eyebrow">${label}</span><h1>${title}</h1><p>${text}</p></div>`;
const placeholder = (title,detail='Photo and caption to be added.') => `<div class="photo-placeholder"><span class="photo-icon" aria-hidden="true">▧</span><strong>${title}</strong><small>${detail}</small></div>`;
const photo = () => {const h=(C.communityHighlights||[]).find(h=>{const e=C.events.find(e=>e.id===h.eventId&&!e.hidden);return e?.photos?.[h.photoIndex||0];});if(!h)return placeholder('Picnic Palooza','Photo and event details to be added.');const e=C.events.find(e=>e.id===h.eventId),p=e.photos[h.photoIndex||0];return `<figure class="featured-photo"><img class="real-photo" src="${esc(p.src)}" alt="${esc(p.alt)}"><figcaption><strong>${esc(e.title)}</strong><br>${esc(p.caption)}${e.photoCredit?`<br><small>${esc(e.photoCredit)}</small>`:''} · ${link('events/'+encodeURIComponent(e.id),'Event details & gallery')}</figcaption></figure>`;};
function network(){return BearVisual.markup();}
function setupNetwork(){BearVisual.mount();}
function eventDate(e){
 if(!e.start&&e.proposedDate)return planDate(e)+' (tentative) · Time to be announced';
 if(!e.start||!Number.isFinite(Date.parse(e.start)))return 'Date & time to be announced';
 const zone=e.timeZone||'America/Chicago';
 const date=value=>new Intl.DateTimeFormat('en-US',{weekday:'long',year:'numeric',month:'long',day:'numeric',timeZone:zone}).format(new Date(value));
 const time=value=>new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:new Date(value).getUTCMinutes()===0?undefined:'2-digit',timeZone:zone}).format(new Date(value));
 const end=e.end&&Number.isFinite(Date.parse(e.end))?e.end:null;
 if(e.id==='general-interest'||e.id==='workshop-1'||e.id==='service-event-2026'||e.id==='spooky-stories-2026'||e.id==='resume-linkedin-2026'){
  const startTime=time(e.start),endTime=end?time(end):null;
  const sameDay=end&&date(e.start)===date(end);
  const sharedPeriod=sameDay&&startTime.match(/(AM|PM)$/)?.[0]===endTime.match(/(AM|PM)$/)?.[0];
  return date(e.start)+' · '+(sharedPeriod?startTime.replace(/\s*(AM|PM)$/,''):startTime)+(end?'–'+(sameDay?'':date(end)+' · ')+endTime:'');
 }
 return date(e.start)+' · '+time(e.start)+(end?'–'+(date(end)!==date(e.start)?date(end)+' · ':'')+time(end):'')+' ('+zone+')';
}
function eventMedia(e,detail=false){if(!detail&&e.flyer&&e.photos?.length){const p=e.photos[e.previewPhotoIndex??e.mainPhotoIndex??0];return `<div class="past-gallery"><figure><img src="${esc(e.flyer)}" alt="${esc(e.flyerAlt||e.title+' promotional flyer')}" loading="lazy"><figcaption>Promotional flyer</figcaption></figure><figure><img src="${esc(p.src)}" alt="${esc(p.alt)}" loading="lazy"><figcaption>${esc(p.caption)}</figcaption></figure></div>`;}const p=e.photos?.[e.mainPhotoIndex];return `${p?`<figure class="event-promotion"><img class="event-flyer" src="${esc(p.src)}" alt="${esc(p.alt)}"><figcaption>${esc(p.caption)}</figcaption></figure>`:""}${e.image?`<figure class="event-promotion"><img class="event-flyer" src="${esc(e.image)}" alt="${esc(e.imageAlt||e.title+' promotional artwork')}">${e.imageCaption?`<figcaption>${esc(e.imageCaption)}</figcaption>`:''}</figure>`:''}${e.flyer&&e.mainPhotoIndex!==undefined?`<p><a class="text-link" href="${esc(e.flyer)}" target="_blank" rel="noopener">View original promotional flyer ↗</a></p>`:e.flyer?`<figure class="event-promotion"><img class="event-flyer" src="${esc(e.flyer)}" alt="${esc(e.flyerAlt||e.title+' promotional flyer')}"><figcaption>Promotional flyer</figcaption></figure>`:''}`;}
function eventGallery(e){return `<h3 class="section-sub">Event photos</h3>${e.photoCredit?`<p class="missing">${esc(e.photoCredit)}</p>`:""}${e.photos?.length?`<div class="past-gallery">${e.photos.map(p=>`<figure><img src="${esc(p.src)}" alt="${esc(p.alt)}" loading="lazy"><figcaption>${esc(p.caption)}</figcaption></figure>`).join('')}</div>`:placeholder('Event photos coming soon.','Photos will be added when available.')}`;}
function pastEventCard(e,detail=false){
 // Preserve the approved Picnic Palooza recap and two-image layout.
 if(e.id==='picnic-palooza-2026')return `<article class="card event-row" id="${esc(e.id)}"><h3>${esc(e.title)}</h3><p>${esc(new Intl.DateTimeFormat('en-US',{dateStyle:'long',timeZone:e.timeZone||'America/Chicago'}).format(new Date(e.start)))} · ${esc(e.location)}</p><div class="past-gallery">${(detail?(e.photos||[]):(e.photos||[]).slice(0,2)).map(p=>`<figure><img src="${esc(p.src)}" alt="${esc(p.alt)}" loading="lazy"><figcaption>${esc(p.caption)}</figcaption></figure>`).join('')}</div><p>${esc(e.description)}</p>${e.url?safeLink(e.url,e.urlLabel||'Event details'):''}${!detail&&hasEventDetails(e)?link('events/'+encodeURIComponent(e.id),'Event details & gallery'):''}</article>`;
 return eventCard(e,false,false,true);
}
function eventDescription(e){return esc(e.description).replace(/\n\n/g,'</p><p>').replace('Please bring a laptop.','<strong>Please bring a laptop.</strong>');}
function eventLinkLabel(e){return e.photos?.length?'Event details & gallery':'Event details';}
function eventCard(e,compact=false,detail=false,past=false){return `<article class="card event-row" id="${esc(e.id)}"><h${compact?'2':'3'}>${esc(e.title)}</h${compact?'2':'3'}>${e.status&&e.status!=='Confirmed'?badge(esc(e.status)):''}${eventMedia(e,detail)}<p>${eventDescription(e)}</p><p>${esc(eventDate(e))}<br>${esc(e.location||'Location to be announced')}</p>${compact?'':`${e.food?`<p>${esc(e.food)}</p>`:''}${e.details?`<p>${esc(e.details)}</p>`:''}${e.mealNote?`<p>${esc(e.mealNote)}</p>`:''}${e.virtual?`<p>${esc(e.virtual)}</p>`:''}<div class="advisor-links">${e.url?safeLink(e.url,e.urlLabel||'Official event details'):''}${e.registration?safeLink(e.registration,'Organizer’s registration page'):''}</div>${e.sponsor?`<p class="missing">Event sponsor: ${esc(e.sponsor)}</p>`:''}${past?`${e.recap?`<h3>Recap</h3><p>${esc(e.recap)}</p>`:''}${detail||!e.photos?.length?(e.photos?.length?eventGallery(e):''):e.photoCredit?`<p class="missing">${esc(e.photoCredit)}</p>`:""}`:''}`}${!detail&&hasEventDetails(e)?link('events/'+encodeURIComponent(e.id),eventLinkLabel(e)):''}</article>`;}
function hasEventDetails(e){return !e.detailsPending&&(e.status==='Confirmed'||e.photos?.length||e.details||e.recap||e.registration||e.url);}
function featuredEvent(){const e=BearEvents.next(C.events),undated=BearEvents.classify(C.events).planned;return `<div class="event-feature"><section class="section split"><div><span class="eyebrow">Up next</span><h2>${e?'Our next event.':'Upcoming events'}</h2>${e?'':`<p>No upcoming event has a confirmed date yet.${undated.length?' Details for the next gathering are being finalized.':''}</p>`}${link('events','View all events ↗')}</div>${e?eventCard(e,true):undated.length?eventCard(undated[0],true):'<div class="card"><h3>Check back soon.</h3><p>Upcoming events will appear here as they are announced.</p></div>'}</section></div>`;}

function home(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">Baylor’s artificial intelligence club</span><h1 class="entrance"><span>Learn AI.</span><span>Build with AI.</span><em>Connect with AI.</em></h1><p>Learn how AI works, build projects around your interests, and meet people who want to learn alongside you.</p><div class="actions">${link('join','Join BearAI <span aria-hidden="true">↗</span>','button')}${link('about','Get to know us <span aria-hidden="true">↗</span>')}</div><p class="welcome-note">All majors. All experience levels. Your curiosity is enough.</p></div>${network()}</section>
${C.sections.activities?`<section class="section"><div class="section-heading"><div><span class="eyebrow">Room to explore</span><h2>Find your starting point.</h2></div><p>You don’t need to have it all figured out.<br>Start with a question.</p></div><div class="cards"><article class="card explore-card explore-learn"><span class="number">01 / LEARN</span><h3>Make sense of AI.</h3><p>New to AI? Start with the ideas, ask questions, and explore at your own pace.</p>${link('resources','Learning resources ↗')}</article><article class="card explore-card explore-build"><span class="number">02 / BUILD</span><h3>Turn curiosity into practice.</h3><p>Explore the project showcase as BearAI’s next chapter takes shape.</p>${link('projects','Explore projects ↗')}</article><article class="card explore-card explore-connect"><span class="number">03 / CONNECT</span><h3>Meet a different perspective.</h3><p>Find a community of students across majors, brought together by an interest in AI.</p>${link('community','Meet the community ↗')}</article></div></section>`:''}
${C.sections.featuredEvent?featuredEvent():''}
<section class="section closing-section"><div class="callout"><div><h2>Come as you are.<br>See what you can become.</h2><p>Your major doesn’t define your place in AI.</p><p class="closing-support">Start with a beginner guide, bring a question to a meeting, or share an idea for a project.</p>${link('resources','Explore beginner resources ↗')}</div></div></section>`;}
function about(){return intro('About BearAI','AI belongs to everyone.','BearAI is Baylor’s student organization for artificial intelligence, machine learning, and emerging AI technologies.')+`<section class="section"><div class="split"><div><span class="eyebrow">Our mission</span><h2>Learn together.<br>Think across disciplines.</h2><p>We bring students together to explore AI with curiosity, openness, and a willingness to learn. Every major and every experience level belongs here.</p></div><div class="card"><h3>Built around what you want to learn.</h3><p>Member interests help shape the workshops we plan and the projects we explore.</p><p>Dr. Zhao and the officers work together to turn those interests into opportunities to learn. With his guidance and the team’s coordination, we aim to help students build useful skills and experience and explore where AI fits into their studies and career goals.</p>${link('people','Meet the people ↗')}</div></div><div class="section-sub constitution-section"><h2>How BearAI is organized</h2><p>BearAI’s constitution sets out a welcoming environment for AI education, discussion, and participation across the Baylor community. Its goals connect theoretical understanding with practical technical skills, ethical AI use, and wider participation in AI.</p><div class="cards about-goals"><article class="card"><h3>Understand and participate.</h3><p>Explore AI ideas through discussion and develop the knowledge and practical skills to take part.</p></article><article class="card"><h3>Use AI thoughtfully.</h3><p>Ethical use and a diverse, welcoming AI community are central to BearAI’s goals.</p></article><article class="card"><h3>A place to get involved.</h3><p>Eligible registered Baylor students can join without prior technical experience. Dues are not required for membership or active status.</p></article></div><p>Want to learn more about how BearAI works? Take a look at our constitution.</p><a class="text-link" href="${esc(C.constitution)}" target="_blank" rel="noopener">View BearAI constitution (PDF)</a></div>${C.sections.history?`<div class="section-sub"><span class="eyebrow">Our story</span><h2>The story so far.</h2><div class="card">${badge('History to be completed')}<p>Founding details, previous milestones, and the club’s earlier chapters will appear here after they have been verified.</p></div></div>`:''}</section>`;}
function officerCard(o,advisor=false){return `<article class="card">${o.photo?`<div class="portrait-frame ${o.graduated?'small-original':''}"><img class="avatar officer-photo ${o.graduated?'small-original':''}" style="object-position:${esc(o.position||'50% 30%')};transform:scale(${o.scale||1});transform-origin:${esc(o.position||'50% 30%')}" src="${esc(o.photo)}" alt="Portrait of ${esc(o.name)}" loading="lazy"></div>`:`<div class="avatar" aria-label="Portrait placeholder">${esc(o.name?.[0]||'—')}</div>`}<p class="role">${o.graduated?'Former ':''}${esc(o.role)}</p><h3>${esc(o.name||'Appointment pending')}</h3>${advisor?`${o.bio?`<p>${esc(o.bio)}</p>`:''}<div class="advisor-links">${o.facultyProfile?safeLink(o.facultyProfile,'Baylor faculty profile'):''}${safeLink(o.website,'Personal website')}</div>`:`<dl class="officer-facts"><div><dt>Major / program</dt><dd>${esc(o.major||'To be added')}</dd></div><div><dt>${o.graduated?'Graduated':'Expected graduation'}</dt><dd>${esc(o.graduated||o.graduationYear||'To be added')}</dd></div></dl>${!o.name?'<p class="missing">Secretary appointment not yet confirmed.</p>':!o.photo?'<p class="missing">Photo to be added.</p>':''}`}${o.interests?`<p>${esc(o.interests)}</p>`:''}</article>`;}
function people(){return intro('People','A shared curiosity.<br>A student-led community.','Meet the current leadership and faculty advisor helping shape BearAI’s next chapter.')+`<section class="section"><div class="cards people">${C.officers.map(o=>officerCard(o)).join('')}${officerCard(C.advisor,true)}</div>${C.formerAdvisors?.length?`<div class="section-sub"><h2>Former faculty advisors</h2><div class="cards people">${C.formerAdvisors.map(o=>officerCard(o,true)).join('')}</div></div>`:''}${C.sections.pastOfficers?`<div class="section-sub"><h2>Past officers</h2>${C.pastOfficers.length?`<div class="cards people">${C.pastOfficers.map(o=>officerCard(o)).join('')}</div>`:`<div class="card">${badge('Records to be confirmed')}<p>Previous officers and their terms of service will be listed once verified.</p></div>`}</div>`:''}</section>`;}

function planDate(e){const value=e.start||e.proposedDate;if(!value)return 'TBD';return new Intl.DateTimeFormat('en-US',{month:'long',day:'numeric',timeZone:e.start?(e.timeZone||'America/Chicago'):'UTC'}).format(new Date(value));}
function semesterPlan(groups){const records=C.events.filter(e=>!e.hidden&&!e.cancelled&&(e.semester==='Fall 2026'||groups.planned.includes(e)));records.sort((a,b)=>(Date.parse(a.start||a.proposedDate)||Infinity)-(Date.parse(b.start||b.proposedDate)||Infinity));return '<div class="section-sub semester-plan"><h2>Fall 2026</h2><p>Our semester plans are subject to change based on event approvals, speaker availability, room reservations, and coordination with collaborating organizations. Confirmed events appear in Upcoming Events above.</p><table class="semester-table"><thead><tr><th scope="col">Date</th><th scope="col">Event</th><th scope="col">Status</th></tr></thead><tbody>'+records.map(e=>'<tr><td data-label="Date">'+esc(planDate(e))+'</td><td data-label="Event"><strong>'+esc(e.title)+'</strong>'+((e.flyer||e.image)&&!e.completed&&e.status!=='Confirmed'?eventMedia(e):'')+(hasEventDetails(e)?'<p>'+link('events/'+encodeURIComponent(e.id),eventLinkLabel(e))+'</p>':'')+'</td><td data-label="Status">'+badge(e.completed?'Completed':e.status==='Confirmed'?'Confirmed':e.detailsPending?'Tentative — details pending':'Tentative')+'</td></tr>').join('')+'</tbody></table><p>The three AI workshops are intended to form BearAI’s main technical progression this semester.</p></div>';}
function events(){const groups=BearEvents.classify(C.events),upcoming=[...groups.ongoing,...groups.upcoming];return intro('Events','BearAI events','Upcoming gatherings, workshops, and general meetings. Explore the details below as the semester takes shape.')+`<section class="section"><h2>Upcoming Events</h2><div class="event-list">${upcoming.length?upcoming.map(e=>eventCard(e)).join(''):'<div class="card"><p>No upcoming events have a confirmed date yet. Check back for the semester’s announcements.</p></div>'}</div>${semesterPlan(groups)}${C.sections.pastEvents?`<div class="section-sub"><h2>Past Events</h2>${groups.past.length?groups.past.map(e=>pastEventCard(e)).join(''):`<div class="card">${badge('Archive to be completed')}<p>Verified event descriptions, dates, and photos will be added here.</p></div>`}</div>`:''}</section>`;}

function resources(){return intro('Resources','Start learning AI.','New to Python, machine learning, or AI? There’s room to start at your own pace, with no prior experience required.')+`<div class="section resource-sections">${window.BEAR_RESOURCES.map(category=>`<section class="resource-category"><h2>${esc(category.title)}</h2><p class="category-description">${esc(category.description)}</p><div class="resource-courses">${category.courses.map(course=>`<article class="card resource-course"><h3><a href="${esc(course.url)}" target="_blank" rel="noopener noreferrer">${esc(course.title)}</a></h3>${course.paragraphs.map(p=>`<p>${p.italic?`<em>${esc(p.text)}</em>`:esc(p.text)}</p>`).join('')}</article>`).join('')}</div></section>`).join('')}</div>`;}
function collaborationActivities(entry){
 const events=(entry.eventIds||[]).map(id=>C.events.find(e=>e.id===id&&!e.hidden&&!e.cancelled)).filter(Boolean);
 return events.length?`<ul class="collaboration-activities">${events.map(e=>{
  const value=e.start||e.proposedDate;
  const date=value?new Intl.DateTimeFormat('en-US',{month:'long',day:'numeric',year:'numeric',timeZone:e.start?(e.timeZone||'America/Chicago'):'UTC'}).format(new Date(value)):'Date unknown';
  const status=e.completed?'Completed':e.status==='Confirmed'?'Scheduled':'Planned, subject to confirmation';
  return `<li><strong>${esc(date)}</strong> · ${esc(e.title)}<br><span class="collaboration-status">${status}</span>${hasEventDetails(e)?`<div>${link('events/'+encodeURIComponent(e.id),'Event details')}</div>`:''}</li>`;
 }).join('')}</ul>`:'';
}
function connectionEntry(e){return `<article class="card connection-entry ${e.type==='Collaboration'?'collaboration-entry':''}"><div class="organization-logo ${e.logoDark?'logo-dark':' '}">${e.logo?`<img src="${esc(e.logo)}" alt="${esc(e.affiliation)} logo">`:esc(e.affiliation)}</div><div><h3>${esc(e.name)}</h3>${e.bearRole?`<span class="badge">${esc(e.bearRole)}</span>`:""}<p>${esc(e.relationship)}</p>${e.eventIds?collaborationActivities(e):''}${e.website?safeLink(e.website,e.type==='Collaboration'?"Connect ↗":"Visit website ↗"):""}</div></article>`;}
function connections(){const entries=C.connections.filter(e=>e.verified);const categories=[['Guest Speakers','Guest speaker','Confirmed guests, their affiliation, and what they shared with BearAI.'],['Collaborations','Collaboration','Verified relationships and the specific work or activity connecting them to BearAI.'],['Where They Are Now','Alumni destination','Former officers and advisors, and where their paths have taken them.']];return intro('Connections','People connected<br>with BearAI.','Guest speakers, collaborations, professional connections, and the paths of former officers and advisors.')+`<section class="section">${C.sections.connections?`<div class="connection-categories">${categories.map(([title,type,description])=>`<section class="connection-category"><h2>${title}</h2>${description?`<p>${description}</p>`:''}${type==='Alumni destination'?'<p class="missing connection-source">Details checked on LinkedIn by BearAI leadership. Last updated September 15, 2026. Dr. Rivas’s information was verified on <a href="https://www.rivas.ai/" target="_blank" rel="noopener noreferrer">his website</a>.</p>':''}<div class="connections-list">${entries.filter(e=>e.type===type||(type==='Alumni destination'&&e.type==='Former advisor destination')).map(connectionEntry).join('')||`<div class="card">${badge('Details to be verified')}<p>Entries will be added here as details are confirmed.</p></div>`}</div></section>`).join('')}</div><p class="missing">An individual’s employer or school does not imply sponsorship or partnership with BearAI.</p>`:''}</section>`;}
function recognition(){return intro('Awards & recognition','Recognizing achievement.','Celebrating the achievements of our members and the BearAI community.')+`<section class="section achievement-list">${C.recognition.filter(r=>r.verified).map(r=>`<article class="card achievement"><img class="real-photo" src="${esc(r.photo)}" alt="BearAI Team #3 at the 2025 AI Venture Challenge award presentation"><div><span class="eyebrow">${esc(r.year)} · ${esc(r.recipient)}</span><h2>${esc(r.title)}</h2><p>${esc(r.description)}</p>${safeLink(r.url,'About the competition')}</div></article>`).join('')}</section>`;}
function projects(){return intro('Projects','From “what if”<br>to what’s possible.','Explore BearAI’s hands-on projects and workshop materials.')+`<section class="section">${C.sections.projects?`<div class="cards project-list">${C.projects.map(p=>`<article class="card">${p.status?badge(esc(p.status)):''}<h2>${esc(p.title)}</h2><p>${esc(p.description)}</p>${p.topics?`<p class="project-topics"><strong>Topics:</strong> ${p.topics.map(esc).join(' · ')}</p>`:''}${p.id==='ai-study-assistant'?link('projects/'+p.id,'View Project →','button'):safeLink(p.github,'View on GitHub ↗')}</article>`).join('')}</div>`:''}<div class="quiet"><p>New to building with AI? You’re welcome here, even if you’ve never written a line of code.</p>${link('join','Start with the community ↗')}</div></section>`;}
function studyResource(m){return `<article class="card material-card"><div><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p></div><a class="button" href="${esc(m.url||m.file)}" target="_blank" rel="noopener noreferrer">${esc(m.label)} <span class="material-format">${esc(m.format||'PDF ↗')}</span></a></article>`;}
function studyAssistant(){
 const project=C.projects.find(p=>p.id==='ai-study-assistant');
 const workshop=C.events.find(e=>e.id===project.workshopEventId);
 const materials=[...project.materials,...(workshop?.materials||[])];
 return intro('Project',esc(project.title),'Build a personalized AI study assistant across three hands-on BearAI workshops.')+`
 <div class="section study-project">
  <div class="study-introduction">
   ${link('projects','← All projects','text-link event-return')}
   <p>Start by designing how your assistant should behave, turn those instructions into a Python application, and then introduce retrieval so it can work with larger collections of notes and documents.</p>
   <p>Each participant builds and modifies their own assistant.</p>
  </div>
  <section class="study-section" aria-labelledby="study-progression">
   <h2 id="study-progression">The Three-Part Progression</h2>
   <p class="study-flow">Design → Code → Improve</p>
   <div class="cards">
    <article class="card"><span class="number">01 / DESIGN</span><h3>Prompting and Evaluation</h3><p>Define how your assistant explains concepts, creates quizzes and flashcards, uses course notes, and responds when information is missing. No programming is required for this first workshop.</p></article>
    <article class="card"><span class="number">02 / CODE</span><h3>Python and an AI API</h3><p>Turn the behaviors explored in Workshop 1 into a small Python application that communicates with an AI model.</p></article>
    <article class="card"><span class="number">03 / IMPROVE</span><h3>Retrieval and RAG</h3><p>Introduce retrieval-augmented generation: finding relevant information in a collection of documents and supplying it to the model before it responds.</p></article>
   </div>
  </section>
  <section class="study-section" aria-labelledby="study-workshop-1">
   <span class="eyebrow">Workshop 1${workshop?.completed?' · Completed':''}</span><h2 id="study-workshop-1">Design a Prompt-Based Study Assistant</h2>
   <p>Workshop 1 is a prompt engineering workshop: participants use a standard AI chatbot to design, test, and improve instructions for an AI study assistant. They will define its goals, provide relevant context, establish rules, evaluate its responses, and revise their instructions.</p>
   <p>By the end, participants should be able to:</p>
   <ul class="study-list"><li>Explain what a prompt is.</li><li>Identify useful goals, context, rules, and output requirements.</li><li>Recognize unsupported information and instruction-following failures.</li><li>Evaluate responses for accuracy and usefulness.</li><li>Improve a prompt through repeated testing.</li></ul>
  </section>
  <section class="study-section study-materials" aria-labelledby="workshop-1-materials">
   <h2 id="workshop-1-materials" tabindex="-1">Workshop 1 Materials</h2>
   ${materials.map(studyResource).join('')}
   <details class="study-explanation"><summary>Why Are the Notes Fictional?</summary><p>The Virelia Star System is fictional and was created specifically for this workshop. Its invented facts are supplied in these notes, so the model should use this material rather than rely on general knowledge from its training. Your prompt should instruct the assistant to answer from the notes and acknowledge when information is missing. This lets us test whether it follows those instructions or generates unsupported information.</p></details>
  </section>
  <div class="study-section study-practice">
   <section aria-labelledby="study-activities"><h2 id="study-activities">What Participants Will Do</h2>
    <ol class="study-list"><li><strong>Design:</strong> Decide how the assistant should behave.</li><li><strong>Test:</strong> Try the shared workshop questions.</li><li><strong>Challenge:</strong> Ask questions the notes cannot answer.</li><li><strong>Evaluate:</strong> Check accuracy, use of the notes, instruction-following, and usefulness.</li><li><strong>Improve:</strong> Revise the prompt and test again.</li></ol>
    <p class="study-flow">Version 1 → Test → Evaluate → Version 2</p>
   </section>
   <section aria-labelledby="study-framework"><h2 id="study-framework">A Simple Prompting Framework</h2>
    <table class="study-framework"><thead><tr><th scope="col">Element</th><th scope="col">Question</th></tr></thead><tbody>${[['Goal','What do you want the AI to do?'],['Context','What information does it need?'],['Rules','What should it do or avoid doing?'],['Output','What should the response look like?']].map(([element,question])=>`<tr><th scope="row">${element}</th><td>${question}</td></tr>`).join('')}</tbody></table>
    <p>Prompting is iterative: <strong>Define → Test → Evaluate → Improve.</strong></p>
   </section>
  </div>
  <section class="study-section study-takeaway" aria-labelledby="study-takeaway"><h2 id="study-takeaway">Workshop 1 Takeaway</h2><p>Participants should leave with reusable instructions describing how their assistant uses notes, explains material, quizzes them, provides feedback, and handles missing information.</p><p><strong>Save your prompt—you’ll build on these ideas in Workshop 2.</strong></p></section>
  <section class="study-section" aria-labelledby="study-workshop-2">
   <span class="eyebrow">02 / CODE</span><h2 id="study-workshop-2">Workshop 2 — Code the Study Assistant</h2>
   <p>Workshop #2 turns the study-assistant behavior explored in Workshop #1 into a working Python application. Participants will use Google Colab and the Gemini API to connect Python to an AI model, build multiple study modes, make the assistant interactive, and customize its behavior.</p>
   <p>We’ll learn the Python syntax needed to understand and modify this application, one step at a time.</p>
   <p><strong>By the end, participants should be able to:</strong></p>
   <ul class="study-list"><li>Explain at a basic level how a Python program communicates with an AI model through an API.</li><li>Use their Workshop #1 prompt as the base behavior for an application.</li><li>Build a prompt in Python using instructions, notes, a study mode, and a user request.</li><li>Use Explain, Quiz, and Flashcard modes.</li><li>Accept user input and use it to control application behavior.</li><li>Build an interactive quiz that generates a question, accepts an answer, and returns feedback.</li><li>Add or customize their own study mode.</li></ul>
  </section>
  <section class="study-section study-materials" aria-labelledby="workshop-2-resources">
   <h2 id="workshop-2-resources">Workshop 2 Resources</h2>
   ${project.workshop2Resources.map(studyResource).join('')}
  </section>
  <section class="study-section" aria-labelledby="study-further">
   <div class="card study-optional"><span class="eyebrow">Take It Further</span><h2 id="study-further">Turn Your Study Assistant Into a GitHub Project</h2>
    <p>Your completed Colab notebook already contains the pieces of a working Python application. If you want to turn it into a cleaner portfolio project, you can move the finished program into a normal Python project and publish it on GitHub.</p>
    <p><strong>This is optional and is not required for Workshop #3.</strong></p>
    ${link('projects/ai-study-assistant/github','GitHub Project Setup Guide →','button')}
   </div>
  </section>
  <section class="study-section" aria-labelledby="study-workshop-3">
   <span class="eyebrow">03 / IMPROVE</span><h2 id="study-workshop-3">Workshop 3 — Add Retrieval</h2>
   <p>Our Workshop #2 application sends all of the Virelia notes to Gemini with every request. That works while the notes are small, but it does not scale well to dozens of lectures or hundreds of pages.</p>
   <p>Workshop #3 will introduce retrieval-augmented generation (RAG): finding the relevant information first, then supplying that context to the AI model before it responds.</p>
   <p><strong>Before Workshop #3:</strong></p>
   <ul class="study-list"><li>Save your completed Workshop #2 Colab.</li><li>Keep access to your Gemini API key.</li><li>Bring your laptop and Google account.</li><li>GitHub setup is optional and is not required.</li></ul>
   <p>Missed Workshop #2? You can still join Workshop #3 using starter materials.</p>
  </section>
  <div class="quiet"><div class="actions">${link('events','View Upcoming Events')}${safeLink(C.join.groupme,'Join GroupMe ↗')}</div><p class="study-signoff">Learn AI · Build with AI · Connect through AI</p></div>
 </div>`;
}

function studyGithub(){
 const code=text=>`<pre class="study-code"><code>${esc(text)}</code></pre>`;
 return intro('Project Guide','Turn Your Study Assistant Into a GitHub Project','The Workshop #2 Colab is designed for learning: the program is split across cells, explanations are mixed with the code, and some cells exist only for testing. This optional guide shows how to turn your finished notebook into a normal Python project that you can run on your computer and publish to GitHub.')+`
 <div class="section study-guide">
<div class="study-introduction">${link('projects/ai-study-assistant','← Back to AI Study Assistant','text-link event-return')}<div class="card study-optional"><strong>This is optional and is not required for Workshop #3.</strong></div></div><section class="study-section" aria-labelledby="guide-overview"><h2 id="guide-overview">From Colab to a Python Project</h2><p>Google Colab lets us build and run Python one cell at a time. A normal Python project puts the finished application code into files that can be run from your computer.</p>${code("ai-study-assistant/\n├── app.py\n├── requirements.txt\n├── README.md\n└── .gitignore")}<ul class="study-list"><li><code>app.py</code> — The finished Python application. This is where the useful code from your Colab will be combined.</li><li><code>requirements.txt</code> — A list of the Python libraries your program needs.</li><li><code>README.md</code> — Documentation explaining what the project does, how to set it up, and how to run it.</li><li><code>.gitignore</code> — A list of files Git should ignore, such as local environments or files that may contain secrets.</li></ul><p>Think of the Colab as the guided construction version of the project and <code>app.py</code> as the cleaned finished version.</p></section>
  <section class="study-section" aria-labelledby="guide-python"><h2 id="guide-python">1. Install Python</h2><p>Colab already gives us Python in the browser. To run the project directly on your own computer, you need Python installed locally.</p><h3>Windows</h3><p>Install a current supported Python 3 version using the official installation tools from ${safeLink("https://www.python.org/downloads/","Python.org ↗")}. After installation, open Command Prompt, PowerShell, or the VS Code terminal and run:</p>${code("python --version")}<p>You can also try:</p>${code("py --version")}<p>If either command prints a Python 3 version, Python is available from your terminal.</p><h3>macOS</h3><p>If you do not already have a supported Python 3 version, install one from ${safeLink("https://www.python.org/downloads/","Python.org ↗")}. Open Terminal and check:</p>${code("python3 --version")}<p>macOS commonly uses the command <code>python3</code> instead of <code>python</code>.</p></section>
  <section class="study-section" aria-labelledby="guide-folder"><h2 id="guide-folder">2. Create Your Project</h2><p>A terminal lets you type commands to open folders, install libraries, and run your program. Type the terminal commands in this guide there, not inside <code>app.py</code>.</p><p>The easiest approach is to open your project folder in VS Code first, then choose <strong>Terminal → New Terminal</strong>; the terminal usually starts inside that folder. These basic commands help you check where you are:</p><ul class="study-list"><li><code>cd folder-name</code> — move into a folder; replace <code>folder-name</code> with its actual name.</li><li><code>cd ..</code> — move back one folder.</li><li><code>dir</code> — list files in the current folder on Windows.</li><li><code>ls</code> — list files on macOS/Linux; <code>ls -a</code> also shows hidden files such as <code>.gitignore</code>.</li></ul><ol class="study-list"><li>Create a folder such as <code>ai-study-assistant</code>.</li><li>Open that folder in an editor. ${safeLink("https://code.visualstudio.com/","VS Code ↗")} is one beginner-friendly option; another editor is fine.</li><li>Create these four files inside the folder:</li></ol>${code("app.py\nrequirements.txt\nREADME.md\n.gitignore")}<p>Keep your terminal inside <code>ai-study-assistant</code> for the remaining commands. Use <code>dir</code> or <code>ls -a</code> to check that your four files are there. Save each file before running the program.</p></section>
  <section class="study-section" aria-labelledby="guide-app"><h2 id="guide-app">3. Move From Colab to app.py</h2><p>You should NOT copy every Colab cell into <code>app.py</code>. Some notebook cells exist only for teaching, testing, or setup.</p><h3>Keep</h3><p>Move the useful application code into <code>app.py</code>, approximately in this order:</p><ol class="study-list"><li>Imports</li><li>API-key input/setup</li><li>Gemini client and model</li><li>Virelia notes</li><li><code>BASE_INSTRUCTIONS</code></li><li><code>STUDY_MODES</code></li><li><code>ask_ai()</code></li><li><code>build_prompt()</code></li><li><code>quiz_student()</code></li><li>The final menu/application logic</li><li>Any custom modes or features you added</li></ol><p>Define variables and functions before the code that uses them, including custom functions called by the menu. Keep the behavior of your completed Workshop #2 application as you combine the cells.</p><h3>Leave Out</h3><ul class="study-list"><li>Markdown explanation cells</li><li>Workshop directions</li><li>Temporary test cells</li><li>Repeated examples</li><li>Cells used only to verify earlier activities</li><li>The Colab package-install command</li></ul><p>Specifically, do NOT copy this into <code>app.py</code>:</p>${code("!pip install -U google-genai \"google-auth==2.49.0\"")}<p><code>!pip</code> is a Colab/notebook command. In a normal project, the required libraries are listed in <code>requirements.txt</code> and installed from the terminal.</p><p>Colab cells already share the same Python runtime. Putting the useful code cells together in the correct order inside <code>app.py</code> recreates that program as one normal Python script.</p></section>
  <section class="study-section" aria-labelledby="guide-example"><h2 id="guide-example">4. What Does app.py Look Like?</h2><p><strong>This is an organization example, NOT a complete runnable application.</strong> The <code>...</code> lines are placeholders, not working function implementations. Replace them with your working notebook code before running it. Copy the working versions of your functions and menu from your completed Workshop #2 Colab. Preserve your own prompt, modes, model setup, and customizations.</p>${code("import os\nfrom getpass import getpass\nfrom google import genai\n\n# api setup\nos.environ[\"GEMINI_API_KEY\"] = getpass(\"paste your Gemini API key: \")\n\nclient = genai.Client()\n\n# notes\nVIRELIA_NOTES = \"\"\"\nyour workshop notes stay here\n\"\"\"\n\n# general assistant behavior\nBASE_INSTRUCTIONS = \"\"\"\nyour base instructions stay here\n\"\"\"\n\n# study modes\nSTUDY_MODES = {\n    \"1\": \"explain mode instructions\",\n    \"2\": \"quiz mode instructions\",\n    \"3\": \"flashcard mode instructions\"\n}\n\ndef ask_ai(prompt):\n    # use the working code from your completed Workshop #2 notebook\n    ...\n\ndef build_prompt(mode_instruction, user_request):\n    # use the working code from your completed Workshop #2 notebook\n    ...\n\ndef quiz_student(topic):\n    # use the working code from your completed Workshop #2 notebook\n    ...\n\n# main menu / program flow\n# use the completed menu logic from your notebook")}<p>Your exact <code>app.py</code> may look slightly different. The important part is that the useful code from the notebook is now together in one Python file and appears in an order where variables/functions are defined before they are used.</p></section>
  <section class="study-section" aria-labelledby="guide-dependencies"><h2 id="guide-dependencies">5. Add the Required Libraries</h2><p>Put exactly this in <code>requirements.txt</code>:</p>${code("google-genai\ngoogle-auth==2.49.0")}<p>These are the libraries used by the Workshop #2 project. You do not need to install extra libraries that the project does not use.</p><p>Run these commands from inside your <code>ai-study-assistant</code> project folder. If you want to use the optional virtual environment below, create and activate it before installing.</p><h3>Windows</h3>${code("python -m pip install -r requirements.txt")}<p>If your installation uses <code>py</code>, use this instead:</p>${code("py -m pip install -r requirements.txt")}<h3>macOS</h3>${code("python3 -m pip install -r requirements.txt")}</section>
  <section class="study-section" aria-labelledby="guide-venv"><h2 id="guide-venv">Optional: Use a Virtual Environment</h2><p>A virtual environment keeps the libraries for this project separate from other Python projects. You do not need one to understand the workshop project, but it is a good habit for future projects.</p><h3>Windows — Command Prompt</h3>${code("python -m venv .venv\n.venv\\Scripts\\activate")}<p>If using <code>py</code>:</p>${code("py -m venv .venv\n.venv\\Scripts\\activate")}<p>In PowerShell, activation uses <code>.\\.venv\\Scripts\\Activate.ps1</code>. If your computer blocks activation, use Command Prompt for this optional step.</p><h3>macOS</h3>${code("python3 -m venv .venv\nsource .venv/bin/activate")}<p>Seeing <code>(.venv)</code> at the beginning of your terminal prompt usually means the environment is active. When you open a new terminal, return to the project folder and run the activation command again; you do not need to recreate the environment.</p><p>After activation, install the libraries:</p>${code("python -m pip install -r requirements.txt")}<p>On macOS, <code>python3 -m pip install -r requirements.txt</code> also works in the activated environment.</p></section>
  <section class="study-section study-takeaway" aria-labelledby="guide-key"><h2 id="guide-key">6. Keep Your API Key Private</h2><p><strong>Never paste your Gemini API key directly into code that you plan to upload to GitHub.</strong></p><p>The Workshop #2 project uses <code>getpass()</code> to ask for the API key when the program runs. That means the key does not need to be stored inside <code>app.py</code>.</p><h3>Get a Gemini API key</h3><ol class="study-list"><li>Visit ${safeLink("https://aistudio.google.com/apikey","Google AI Studio ↗")}.</li><li>Sign in with a Google account.</li><li>Create an API key using an available Google AI Studio project. If a project is not listed, follow AI Studio’s project setup or import prompts.</li><li>Copy the generated API key.</li><li>Run your application and paste the key when prompted. With <code>getpass()</code>, the key stays hidden as you type or paste; press Enter to continue.</li></ol><p>API availability, quotas, and billing requirements can vary. If you already have a working Workshop #2 key, you can use it. <strong>Never upload your API key to GitHub.</strong></p><p>If you later use a <code>.env</code> file or another local secret file, make sure it is excluded by <code>.gitignore</code>.</p></section>
  <section class="study-section" aria-labelledby="guide-ignore"><h2 id="guide-ignore">7. Add a .gitignore</h2><p>Put these lines in <code>.gitignore</code>:</p>${code("__pycache__/\n.venv/\n.env")}<ul class="study-list"><li><code>__pycache__/</code> — generated Python cache files</li><li><code>.venv/</code> — local virtual environment</li><li><code>.env</code> — commonly used for environment variables/secrets</li></ul><p><code>.gitignore</code> helps prevent these files from being committed, but you should still check your files before pushing.</p></section>
  <section class="study-section" aria-labelledby="guide-readme"><h2 id="guide-readme">8. Write a README</h2><p>Your README is the first thing many people will see when they open your repository. It should explain:</p><ul class="study-list"><li>What the AI Study Assistant does</li><li>What technologies it uses</li><li>What study modes/features it has</li><li>How to install its dependencies</li><li>How to obtain a Gemini API key</li><li>How to run the program</li><li>What you personally customized</li><li>Possible future improvements</li></ul><p>Start with this structure and fill it in with your own project details:</p>${code("# AI Study Assistant\n\n## About\n\n## Features\n\n## Technologies\n\n## Setup\n\n## Running the Program\n\n## Future Improvements")}<p>If you put this project on a portfolio or résumé, customize the README so it accurately reflects what YOU built or changed.</p></section>
  <section class="study-section" aria-labelledby="guide-test"><h2 id="guide-test">9. Run the Project Locally</h2><p>Make sure your terminal is currently inside the project folder, then run:</p><h3>Windows</h3>${code("python app.py")}<p>If your installation uses <code>py</code>, use this instead:</p>${code("py app.py")}<h3>macOS</h3>${code("python3 app.py")}<p>Test that:</p><ul class="study-list"><li>Gemini connects successfully</li><li>Explain mode works</li><li>Flashcard mode works</li><li>Quiz mode works</li><li>The assistant refuses to invent missing information</li><li>Any custom study modes still work</li></ul><p>Fix local errors before uploading the project to GitHub.</p></section>
  <section class="study-section" aria-labelledby="guide-troubleshooting"><h2 id="guide-troubleshooting">Troubleshooting</h2><details class="study-explanation"><summary>Python command is not recognized</summary><h3>Windows</h3>${code("python --version")}<p>If your installation uses <code>py</code>, use this instead:</p>${code("py --version")}<h3>macOS</h3>${code("python3 --version")}<p>If none works, install Python from the official ${safeLink("https://www.python.org/downloads/","Python website ↗")}.</p></details><details class="study-explanation"><summary>ModuleNotFoundError</summary><p>The required packages probably have not been installed in the Python environment you are currently using. Run the appropriate command:</p><h3>Windows</h3>${code("python -m pip install -r requirements.txt")}<p>If your installation uses <code>py</code>, use this instead:</p>${code("py -m pip install -r requirements.txt")}<h3>macOS</h3>${code("python3 -m pip install -r requirements.txt")}</details><details class="study-explanation"><summary>Gemini/API error</summary><ul class="study-list"><li>Check that you entered a valid Gemini API key.</li><li>Check that you have internet access.</li><li>Check that <code>google-genai</code> is installed.</li><li>Check that your Gemini setup code was copied correctly from the completed notebook.</li></ul></details><details class="study-explanation"><summary>It worked in Colab but not locally</summary><ul class="study-list"><li>Verify <code>!pip install ...</code> was NOT copied into <code>app.py</code>.</li><li>Install dependencies using <code>requirements.txt</code>.</li><li>Combine all required code cells into <code>app.py</code>.</li><li>Put variables/functions before the code that uses them.</li><li>Run the command from the project directory.</li></ul></details><details class="study-explanation"><summary>File not found / wrong directory</summary><p>Check your current folder:</p><h3>Windows</h3>${code("dir")}<h3>macOS/Linux</h3>${code("ls -a")}<p>You should see these files before running the project commands. On macOS/Linux, <code>ls</code> lists files; <code>ls -a</code> also shows the hidden <code>.gitignore</code>.</p>${code("app.py\nrequirements.txt\nREADME.md\n.gitignore")}</details></section>
  <section class="study-section" aria-labelledby="guide-repository"><h2 id="guide-repository">10. Create a GitHub Repository</h2><p>Once the program works locally, create a repository on your GitHub account. A repository stores your project files and their saved history.</p><ol class="study-list"><li>Sign in to GitHub and choose New repository.</li><li>Use a name such as <code>ai-study-assistant</code>.</li><li>Choose public if you want it visible as a portfolio project, or private if you do not want it publicly visible yet.</li><li>Leave README, .gitignore, and license initialization unchecked so the repository starts empty; your project files already exist locally.</li><li>Create the repository and keep its page open for the repository URL.</li></ol><h3>Check Git on your computer</h3><p>Git tracks changes to files locally. GitHub hosts Git repositories online so projects can be shared. Before publishing, check that Git is installed by running this in your terminal:</p>${code("git --version")}<p>A Git version number means the installation is working. If Git is not recognized, install it from the official ${safeLink("https://git-scm.com/downloads","Git installation website ↗")}, then reopen your terminal in the project folder.</p><h3>Set your commit author details once</h3>${code("git config --global user.name \"Your Name\"\ngit config --global user.email \"your@email.com\"")}<p>Replace the examples with your own details. These commands identify the author of Git commits and apply to future repositories on this computer; they do not sign you in. Use an email associated with your GitHub account or your GitHub-provided private <code>noreply</code> email from GitHub Settings → Emails. Your chosen author details appear in published commits.</p></section>
  <section class="study-section study-takeaway" aria-labelledby="guide-review"><h2 id="guide-review">11. Check Your Project Before Uploading</h2><p><strong>Before staging anything:</strong></p><ol class="study-list"><li>Open <code>app.py</code>.</li><li>Search for your API key or anything that looks like a secret.</li><li>Confirm <code>.gitignore</code> exists.</li><li>Confirm <code>.env</code>, <code>.venv</code>, and unrelated personal files are not intended for upload.</li></ol><p>The publishing workflow below runs <code>git init</code> first, then:</p>${code("git status")}<p><code>git status</code> shows which files Git currently sees and which files are staged or untracked. Look at the file list carefully before committing. If a secret file is listed, stop and fix it before staging.</p></section>
  <section class="study-section" aria-labelledby="guide-publish"><h2 id="guide-publish">12. Publish the Project</h2><p>From inside your project folder, run these commands one at a time. Pause at both <code>git status</code> checks to inspect the files:</p>${code("git init\ngit status\ngit add .\ngit status\ngit commit -m \"Initial AI Study Assistant\"\ngit branch -M main\ngit remote add origin YOUR_REPOSITORY_URL\ngit push -u origin main")}<ul class="study-list"><li><code>git init</code> — starts Git tracking in the current folder.</li><li><code>git status</code> — shows what Git sees.</li><li><code>git add .</code> — stages the files in the current project directory, selecting them for the next snapshot.</li><li><strong>Second <code>git status</code>:</strong> gives you one more chance to inspect exactly what is about to be committed. Stop if the list includes anything private.</li><li><code>git commit</code> — creates the local snapshot.</li><li><code>git branch -M main</code> — names your current branch main.</li><li><code>git remote add origin</code> — connects your local project to the repository you created on GitHub.</li><li><code>git push</code> — uploads the committed project.</li></ul><p>Replace <code>YOUR_REPOSITORY_URL</code> with the URL of the repository you created. Copy it from that repository’s GitHub page and follow the sign-in prompt when pushing. After <code>git push -u origin main</code> finishes without an error, open your GitHub repository and refresh the page: your project files should appear.</p></section>
  <section class="study-section" aria-labelledby="guide-desktop"><h2 id="guide-desktop">Prefer a Visual Interface?</h2><p>GitHub Desktop can perform the same basic workflow with a graphical interface if you are not comfortable using Git commands yet. You only need to choose one approach.</p><p>${safeLink("https://desktop.github.com/","Get GitHub Desktop ↗")}</p></section>
  <section class="study-section" aria-labelledby="guide-after"><h2 id="guide-after">After You Push</h2><p>Open your repository on GitHub and verify:</p><ul class="study-list"><li><code>app.py</code> is present</li><li><code>requirements.txt</code> is present</li><li><code>README.md</code> is present</li><li><code>.gitignore</code> is present</li><li><code>.env</code> is NOT present</li><li><code>.venv</code> is NOT present</li><li>No API key appears in <code>app.py</code>, the README, commit messages, or other files</li></ul><p><strong>If you accidentally publish an API key, do not just delete it from the file. Revoke that key in Google AI Studio and create a new one.</strong></p></section>
  <section class="study-section" aria-labelledby="guide-updates"><h2 id="guide-updates">Optional: Publish Future Changes</h2><p>After the initial setup and upload, use these commands to update the same repository. Run them from your project folder after saving and testing your changes:</p>${code("git status\ngit add .\ngit commit -m \"Describe your changes\"\ngit push")}<ul class="study-list"><li><code>git status</code> — review tracked, untracked, and staged files. Confirm there are no secrets or unrelated files before continuing.</li><li><code>git add .</code> — stage the files you want to include. Run <code>git status</code> again to check what is staged before committing.</li><li><code>git commit</code> — save a local snapshot; replace the message with a short description of your changes.</li><li><code>git push</code> — upload the new snapshot. Refresh GitHub to confirm your updates appear.</li></ul><p>These commands update your existing repository; you do not need to repeat <code>git init</code> or create another repository.</p></section>
  <section class="study-section" aria-labelledby="guide-build"><h2 id="guide-build">Keep Building</h2><p>The BearAI workshop gives you the foundation. The project becomes more useful as a portfolio piece when you understand it and add your own ideas.</p><p>Optional improvements to explore at your own pace:</p><ul class="study-list"><li>New study modes</li><li>Different prompting behavior</li><li>Use your own notes</li><li>Improved terminal menus</li><li>Save quiz scores/results</li><li>Conversation history</li><li>GUI</li><li>Web interface</li><li>Support for multiple subjects</li><li>Retrieval/RAG from Workshop #3</li></ul><p>None of these improvements are required.</p></section>
  <section class="study-section" aria-labelledby="guide-portfolio"><h2 id="guide-portfolio">Using This as a Project</h2><p>If you understand the code, customize the application, and continue developing it, this can become a small portfolio project demonstrating Python, API integration, prompt design, and AI application development.</p><p>Be ready to explain what you personally changed, how the Gemini API call works, how the prompt is constructed, and how your Python code controls the user experience.</p><p>Do not present BearAI starter code as though every line was independently written from scratch. Focus on what you learned, understood, modified, and added. Credit the BearAI starter notebook.</p></section><div class="quiet actions">${link('projects/ai-study-assistant','← Back to AI Study Assistant')}${link('events','View Upcoming BearAI Events →')}</div>
 </div>`;
}
function community(){const highlights=(C.communityHighlights||[]).map(h=>({event:C.events.find(e=>e.id===h.eventId&&!e.hidden),index:h.photoIndex||0})).filter(h=>h.event?.photos?.[h.index]);return intro('Community','Life at BearAI.','Meet the students, see what we’ve been doing, and explore highlights from club activities.')+`<section class="section">${C.sections.gallery?`<div class="split">${photo()}<div><span class="eyebrow">Community highlights</span><h2>Learning together,<br>beyond the screen.</h2><p>A selection of moments from BearAI activities. Each event keeps its full photo gallery, captions, and recap on the Events page.</p>${highlights.length?'':badge('Picnic Palooza photo and event details to be added')}</div></div><div class="cards section-sub">${highlights.slice(1).map(({event,index})=>{const p=event.photos[index];return `<article class="card"><img class="real-photo" src="${esc(p.src)}" alt="${esc(p.alt)}"><h3>${esc(event.title)}</h3><p>${esc(p.caption)}</p>${event.photoCredit?`<p class="missing">${esc(event.photoCredit)}</p>`:''}${link('events/'+encodeURIComponent(event.id),'View event recap & gallery ↗')}</article>`;}).join('')}</div>`:''}</section>`;}
function eventDetail(id){const event=C.events.find(e=>e.id===id&&!e.hidden&&!e.cancelled);if(!event)return intro('Event unavailable','Event not found.','Use Events to explore the available gatherings.');const past=BearEvents.classify([event]).past.length>0;if(event.id==='picnic-palooza-2026')return intro('Past event',esc(event.title),'A moment from BearAI’s community.')+`<section class="section">${link('events','← All events','text-link event-return')}${pastEventCard(event,true)}</section>`;return intro(past?'Past event':'Event details',esc(event.title),eventDescription(event))+`<section class="section">${link('events','← All events','text-link event-return')}<div class="section-sub">${eventCard(event,false,true,past)}</div></section>`;}
function safeLink(url,label){return /^https:\/\//.test(url||'')?`<a class="text-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`:pending(label);}
function join(){return intro('Join BearAI','Bring your curiosity.<br>You belong here.','All majors. Every experience level. You don’t need a technical background to start exploring AI with us.')+`<section class="section"><div class="cards join-grid">${[['00','Baylor Connect','Please request to join BearAI on Baylor Connect. We’ll accept your request as soon as possible. Joining helps us maintain BearAI’s official membership roster through Baylor.','connect','Open Baylor Connect'],['01','GroupMe','Our main channel for club-wide communication and announcements.','groupme','Join the GroupMe'],['02','Instagram','Follow along with BearAI’s public updates.','instagram','Visit Instagram'],['03','Interest survey','Share what interests you and what you’d like to learn. Your feedback helps shape BearAI. Please take a moment to complete the survey—it’s especially important because your responses help us plan workshops, projects, and events around what you want to learn.','survey','Open interest survey'],['04','Contact us','Have a question? Get in touch with BearAI.','email','Email BearAI']].map(([n,title,desc,key,label])=>`<article class="card ${key==='connect'?'connect-card':''}"><span class="number">${n} / GET CONNECTED</span><h3>${title}</h3><p>${desc}</p>${key==='email'&&C.join.email?`<a class="text-link" href="mailto:${esc(C.join.email)}">${esc(C.join.email)}</a>`:safeLink(C.join[key],label)}</article>`).join('')}</div></section>`;}
// Reapply after fonts and browser restoration settle so QR links survive refresh.
function focusWorkshopMaterials(){
 const [route,query]=location.hash.replace(/^#\/?/,'').split('?');
 if(route!=='projects/ai-study-assistant'||new URLSearchParams(query||'').get('section')!=='workshop-1-materials')return;
 requestAnimationFrame(()=>{
  const target=document.getElementById('workshop-1-materials');
  if(target){target.focus({preventScroll:true});target.scrollIntoView({block:'start',behavior:'instant'});}
 });
}
const pages={'projects/ai-study-assistant/github':studyGithub,'projects/ai-study-assistant':studyAssistant,'':home,about,people,events,resources,connections,recognition,projects,community,join};
function render(focus=false){
  const route=location.hash.replace(/^#\/?/,'').split('?')[0];
  document.querySelector('#nav').innerHTML=routes.map(([path,label])=>`<a href="#/${path}" ${(route===path||(['events','projects'].includes(path)&&route.startsWith(path+'/')))?'aria-current="page"':''} class="${path==='join'?'join-nav':''}">${label}</a>`).join('');
  document.querySelector('#main').innerHTML=route.startsWith('events/')?eventDetail(decodeURIComponent(route.slice(7))):pages[route]?pages[route]():intro('Page not found','Let’s reconnect.','This page doesn’t exist. Use the navigation to return to BearAI.');
  document.title=`${routes.find(r=>r[0]===route)?.[1]||(route==='projects/ai-study-assistant/github'?'GitHub Project Setup Guide':route==='projects/ai-study-assistant'?'AI Study Assistant':route.startsWith('events/')?'Event gallery':'Page not found')} — BearAI`;
  document.querySelector('#nav').classList.remove('open');document.querySelector('.menu').setAttribute('aria-expanded','false');
  setupNetwork();
  BearVisual.scrambleHeadings();
  mountExplore();
  mountEntrances();
  if(focus){document.querySelector('#main').focus();window.scrollTo(0,0);}
  focusWorkshopMaterials();
}
document.querySelector('.menu').addEventListener('click',()=>{const open=document.querySelector('#nav').classList.toggle('open');document.querySelector('.menu').setAttribute('aria-expanded',String(open));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('#nav').classList.contains('open')){document.querySelector('#nav').classList.remove('open');document.querySelector('.menu').setAttribute('aria-expanded','false');document.querySelector('.menu').focus();}});
window.addEventListener('hashchange',()=>render(true));render();
window.addEventListener('pageshow',focusWorkshopMaterials);
if(document.fonts)document.fonts.ready.then(focusWorkshopMaterials);
document.querySelector('footer').innerHTML=`<a class="brand footer-brand" href="#/" aria-label="BearAI home"><img src="assets/BearAI_Logo_Green.png" alt=""><span class="footer-wordmark">Bear<span class="gold">AI</span></span></a><small class="copyright">© ${new Date().getFullYear()} BearAI — Baylor University’s AI student organization. All rights reserved.</small><div class="footer-links">${link('about','About','')}${link('events','Events','')}${link('resources','Resources','')}${link('connections','Connections','')}${link('recognition','Recognition','')}${link('join','Contact & club channels','')}<a href="https://www.baylor.edu/" target="_blank" rel="noopener noreferrer">Baylor University ↗</a></div>`;
// The skip link focuses content without changing the page route.
document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();document.querySelector('#main').focus();document.querySelector('#main').scrollIntoView();});
// Close mobile navigation even when the current page is selected again.
document.querySelector('#nav').addEventListener('click',event=>{if(event.target.closest('a')){document.querySelector('#nav').classList.remove('open');document.querySelector('.menu').setAttribute('aria-expanded','false');}});


function mountExplore(){cleanupExplore();const cards=[...document.querySelectorAll('.explore-card')],media=matchMedia('(prefers-reduced-motion: reduce)');if(!cards.length||media.matches)return;const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('explore-enter');observer.unobserve(entry.target);}}),{threshold:.2});cards.forEach(card=>observer.observe(card));const stop=()=>{observer.disconnect();cards.forEach(card=>card.classList.remove('explore-enter'));media.removeEventListener('change',stop);};media.addEventListener('change',stop);cleanupExplore=stop;}



// Each card reveals once per page visit; content remains readable before entry.
function mountEntrances(){
 cleanupEntrances();
 const targets=[...document.querySelectorAll('.event-row,.closing-section')];
 const media=matchMedia('(prefers-reduced-motion: reduce)');
 if(media.matches||!('IntersectionObserver' in window))return;
 const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{
  if(entry.isIntersecting){entry.target.classList.add('content-enter');observer.unobserve(entry.target);}
 }),{threshold:0,rootMargin:'0px 0px -24px 0px'});
 targets.forEach(target=>observer.observe(target));
 const stop=()=>{observer.disconnect();targets.forEach(target=>target.classList.remove('content-enter'));media.removeEventListener('change',stop);};
 media.addEventListener('change',stop);cleanupEntrances=stop;
}
